'use client';
import { useEffect, useRef, useState } from 'react';
import { Brain, Palette, ScanEye, Server, Sparkles, type LucideIcon } from 'lucide-react';

const ICONS: Record<string, LucideIcon> = { brain: Brain, sparkles: Sparkles, server: Server, scan: ScanEye, palette: Palette };
export interface SkillRow { name: string; label: string; pct: number }
const dots = (pct: number) => (pct >= 80 ? 3 : pct >= 50 ? 2 : 1);

/** Skill group card: a header with the skill count, then pill chips with a 3-dot level meter. Chips pop in when the card scrolls into view. */
export function SkillCard({ title, icon, items }: { title: string; icon: string; items: SkillRow[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const [on, setOn] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setOn(true); io.disconnect(); } }, { threshold: 0.25 });
    io.observe(el); return () => io.disconnect();
  }, []);
  const Icon = ICONS[icon] ?? Sparkles;
  return (
    <div ref={ref} className={`glass skill-card sk2${on ? ' on' : ''}`}>
      <div className="sk-head">
        <span className="sk-icon"><Icon size={24} /></span>
        <div><h3>{title}</h3><p>{items.length} skills</p></div>
      </div>
      <ul className="sk-chips">
        {items.map((s, i) => (
          <li key={s.name} className={`sk-chip lv${dots(s.pct)}`} style={{ transitionDelay: `${i * 70}ms` }} title={s.label}>
            <span className="sk-name">{s.name}</span>
            <span className="sk-meter" role="img" aria-label={s.label}><i /><i /><i /></span>
          </li>
        ))}
      </ul>
    </div>
  );
}
